            <button type="submit" data-testid="crew-member-add">Add member</button>
            @if (memberErrors()[crew.id]; as message) {
              <p role="alert" class="error" data-testid="crew-error">{{ (message) | figure }}</p>
            }
          </form>
        </div>
      }
    </section>
